-- Import staging, provenance, full-library metadata, retained verification and private event records.
BEGIN;
SET LOCAL search_path=pg_catalog;
ALTER TABLE catalog.repositories ADD COLUMN canonical_url text NOT NULL;
ALTER TABLE catalog.snapshots ADD COLUMN tree_oid text;
CREATE TABLE catalog.import_runs(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),snapshot_id uuid NOT NULL REFERENCES catalog.snapshots ON DELETE RESTRICT,request_key text NOT NULL UNIQUE,scope jsonb NOT NULL CHECK(jsonb_typeof(scope)='object'),manifest_digest catalog.digest256 NOT NULL,scanner_version text NOT NULL,state text NOT NULL CHECK(state IN('queued','running','completed','failed','cancelled')),coverage_complete boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalog.import_targets(run_id uuid NOT NULL REFERENCES catalog.import_runs ON DELETE RESTRICT,path text COLLATE "C" NOT NULL,observed_hash catalog.digest256,diagnostic_code text,PRIMARY KEY(run_id,path));
CREATE TABLE catalog.identity_events(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),repository_id uuid NOT NULL REFERENCES catalog.repositories ON DELETE RESTRICT,exercise_id uuid REFERENCES catalog.exercises ON DELETE RESTRICT,kind text NOT NULL,source_path text,target_path text,actor_ref text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalog.source_locations(repository_id uuid NOT NULL REFERENCES catalog.repositories ON DELETE RESTRICT,path text COLLATE "C" NOT NULL,exercise_id uuid NOT NULL REFERENCES catalog.exercises ON DELETE RESTRICT,state text NOT NULL CHECK(state IN('present','absent','quarantined')),generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0),last_event_id uuid NOT NULL REFERENCES catalog.identity_events ON DELETE RESTRICT,PRIMARY KEY(repository_id,path));
CREATE TABLE catalog.source_taxonomies(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),snapshot_id uuid NOT NULL REFERENCES catalog.snapshots ON DELETE RESTRICT,path text NOT NULL,file_hash catalog.digest256 NOT NULL,parser_version text NOT NULL,UNIQUE(snapshot_id,path,file_hash,parser_version));
CREATE TABLE catalog.raw_classifications(source_version_id uuid NOT NULL REFERENCES catalog.source_versions ON DELETE RESTRICT,parser_version text NOT NULL,field text NOT NULL CHECK(field IN('DBsubject','DBchapter','DBsection')),ordinal integer NOT NULL CHECK(ordinal>0),source_line integer CHECK(source_line>0),raw_text text NOT NULL,parsed_value text,PRIMARY KEY(source_version_id,parser_version,field,ordinal));
CREATE TABLE catalog.classification_assessments(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),source_version_id uuid NOT NULL REFERENCES catalog.source_versions ON DELETE RESTRICT,taxonomy_id uuid REFERENCES catalog.source_taxonomies ON DELETE RESTRICT,parser_version text NOT NULL,state text NOT NULL CHECK(state IN('matched','missing','partial','conflicting','malformed','unmapped')),details jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE catalog.mapping_rules(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),release_id uuid NOT NULL REFERENCES catalog.taxonomy_releases ON DELETE RESTRICT,rule_digest catalog.digest256 NOT NULL,definition jsonb NOT NULL,review_state text NOT NULL CHECK(review_state IN('proposed','approved','rejected')),actor_ref text,UNIQUE(release_id,rule_digest));
CREATE TABLE catalog.metadata_candidates(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),source_version_id uuid NOT NULL REFERENCES catalog.source_versions ON DELETE RESTRICT,field text NOT NULL,locale text,value jsonb,origin text NOT NULL,reference jsonb NOT NULL DEFAULT '{}'::jsonb,review_state text NOT NULL CHECK(review_state IN('missing','proposed','approved','rejected','stale')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,source_version_id,review_state));
CREATE TABLE catalog.metadata_reviews(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),candidate_id uuid NOT NULL REFERENCES catalog.metadata_candidates ON DELETE RESTRICT,actor_ref text NOT NULL,decision text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalog.metadata_releases(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),release_key text NOT NULL UNIQUE,state text NOT NULL CHECK(state IN('draft','published','retired')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalog.metadata_selections(release_id uuid NOT NULL REFERENCES catalog.metadata_releases ON DELETE RESTRICT,exercise_id uuid NOT NULL,source_version_id uuid NOT NULL,snapshot_id uuid NOT NULL,locale text NOT NULL,field text NOT NULL,candidate_id uuid NOT NULL,candidate_state text NOT NULL DEFAULT 'approved' CHECK(candidate_state='approved'),PRIMARY KEY(release_id,exercise_id,locale,field),FOREIGN KEY(source_version_id,exercise_id,snapshot_id) REFERENCES catalog.source_versions(id,exercise_id,snapshot_id) ON DELETE RESTRICT,FOREIGN KEY(candidate_id,source_version_id,candidate_state) REFERENCES catalog.metadata_candidates(id,source_version_id,review_state) ON DELETE RESTRICT);
CREATE TABLE catalog.metadata_documents(release_id uuid NOT NULL REFERENCES catalog.metadata_releases ON DELETE RESTRICT,exercise_id uuid NOT NULL,source_version_id uuid NOT NULL,snapshot_id uuid NOT NULL,locale text NOT NULL,title text NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 160),title_sort text COLLATE "C" NOT NULL,description text CHECK(length(description)<=600),reviewed_terms text NOT NULL DEFAULT '',subject_label text,topic_label text,content_language text,difficulty smallint CHECK(difficulty BETWEEN 1 AND 5),difficulty_scale text,estimated_minutes numeric CHECK(estimated_minutes>0 AND estimated_minutes<=480),attribution jsonb NOT NULL DEFAULT '{}'::jsonb,rights_state text NOT NULL DEFAULT 'review-required' CHECK(rights_state IN('review-required','reviewed-with-conditions','restricted')),document tsvector GENERATED ALWAYS AS(setweight(to_tsvector('simple'::regconfig,title),'A')||setweight(to_tsvector('simple'::regconfig,reviewed_terms),'B')||setweight(to_tsvector('simple'::regconfig,coalesce(subject_label,'')||' '||coalesce(topic_label,'')),'C')||setweight(to_tsvector('simple'::regconfig,coalesce(description,'')),'D')) STORED,PRIMARY KEY(release_id,exercise_id,locale),FOREIGN KEY(source_version_id,exercise_id,snapshot_id) REFERENCES catalog.source_versions(id,exercise_id,snapshot_id) ON DELETE RESTRICT,CHECK((difficulty IS NULL AND difficulty_scale IS NULL) OR(difficulty IS NOT NULL AND difficulty_scale='practice-difficulty-v1')));
CREATE INDEX metadata_document_browse ON catalog.metadata_documents(release_id,locale,title_sort,exercise_id);
CREATE INDEX metadata_document_search ON catalog.metadata_documents USING gin(document);
CREATE TABLE catalog.metadata_heads(scope text PRIMARY KEY,release_id uuid NOT NULL REFERENCES catalog.metadata_releases ON DELETE RESTRICT,generation bigint NOT NULL DEFAULT 0 CHECK(generation>=0));
CREATE TABLE catalog.capability_versions(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),capability_key text NOT NULL,version text NOT NULL,UNIQUE(capability_key,version));
ALTER TABLE catalog.profiles ADD COLUMN sealed boolean NOT NULL DEFAULT false;
CREATE TABLE catalog.profile_dimensions(profile_id uuid NOT NULL REFERENCES catalog.profiles ON DELETE RESTRICT,seed integer NOT NULL CHECK(seed BETWEEN 1 AND 2147483647),viewport text NOT NULL CHECK(viewport IN('desktop','mobile')),PRIMARY KEY(profile_id,seed,viewport));
CREATE TABLE catalog.profile_checks(profile_id uuid NOT NULL REFERENCES catalog.profiles ON DELETE RESTRICT,check_key text NOT NULL,PRIMARY KEY(profile_id,check_key));
CREATE TABLE catalog.profile_capabilities(profile_id uuid NOT NULL REFERENCES catalog.profiles ON DELETE RESTRICT,capability_id uuid NOT NULL REFERENCES catalog.capability_versions ON DELETE RESTRICT,status text NOT NULL CHECK(status IN('verified','limited','unsupported')),PRIMARY KEY(profile_id,capability_id));
ALTER TABLE catalog.requirement_sets ADD COLUMN discovery_complete boolean NOT NULL DEFAULT false;
CREATE TABLE catalog.requirement_capabilities(requirement_set_id uuid NOT NULL REFERENCES catalog.requirement_sets ON DELETE RESTRICT,capability_id uuid NOT NULL REFERENCES catalog.capability_versions ON DELETE RESTRICT,PRIMARY KEY(requirement_set_id,capability_id));
ALTER TABLE catalog.environments ADD COLUMN renderer_revision text,ADD COLUMN pg_revision text,ADD COLUMN dependency_digest catalog.digest256,ADD COLUMN runtime_digest catalog.digest256,ADD COLUMN source_manifest_digest catalog.digest256,ADD COLUMN certified boolean NOT NULL DEFAULT false;
CREATE TABLE catalog.verification_workers(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),worker_key text NOT NULL UNIQUE,state text NOT NULL CHECK(state IN('active','revoked')));
CREATE TABLE catalog.verification_runs(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),environment_id uuid NOT NULL REFERENCES catalog.environments ON DELETE RESTRICT,profile_id uuid NOT NULL REFERENCES catalog.profiles ON DELETE RESTRICT,worker_id uuid NOT NULL REFERENCES catalog.verification_workers ON DELETE RESTRICT,manifest_digest catalog.digest256 NOT NULL,target_count integer NOT NULL CHECK(target_count>0),state text NOT NULL CHECK(state IN('queued','running','completed','failed','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,environment_id,profile_id));
CREATE TABLE catalog.verification_targets(run_id uuid NOT NULL REFERENCES catalog.verification_runs ON DELETE RESTRICT,source_version_id uuid NOT NULL,requirement_set_id uuid NOT NULL,PRIMARY KEY(run_id,source_version_id),FOREIGN KEY(requirement_set_id,source_version_id) REFERENCES catalog.requirement_sets(id,source_version_id) ON DELETE RESTRICT,UNIQUE(run_id,source_version_id,requirement_set_id));
CREATE TABLE catalog.case_attempts(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),run_id uuid NOT NULL,source_version_id uuid NOT NULL,requirement_set_id uuid NOT NULL,environment_id uuid NOT NULL,profile_id uuid NOT NULL,seed integer NOT NULL,viewport text NOT NULL,ordinal integer NOT NULL CHECK(ordinal>0),state text NOT NULL CHECK(state IN('passed','failed','error','blocked')),source_verified boolean NOT NULL,checks jsonb NOT NULL CHECK(jsonb_typeof(checks)='object'),correct_score numeric CHECK(correct_score BETWEEN 0 AND 1),cleared_score numeric CHECK(cleared_score BETWEEN 0 AND 1),limitations jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(limitations)='array'),failure_code text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(run_id,source_version_id,requirement_set_id) REFERENCES catalog.verification_targets(run_id,source_version_id,requirement_set_id) ON DELETE RESTRICT,FOREIGN KEY(run_id,environment_id,profile_id) REFERENCES catalog.verification_runs(id,environment_id,profile_id) ON DELETE RESTRICT,FOREIGN KEY(profile_id,seed,viewport) REFERENCES catalog.profile_dimensions(profile_id,seed,viewport) ON DELETE RESTRICT,UNIQUE(run_id,source_version_id,seed,viewport,ordinal),UNIQUE(id,run_id,source_version_id,requirement_set_id,environment_id,profile_id,seed,viewport));
CREATE TABLE catalog.evidence_bundles(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),run_id uuid NOT NULL,source_version_id uuid NOT NULL,requirement_set_id uuid NOT NULL,environment_id uuid NOT NULL,profile_id uuid NOT NULL,supersedes_id uuid REFERENCES catalog.evidence_bundles ON DELETE RESTRICT,selection_reason text NOT NULL,FOREIGN KEY(run_id,source_version_id,requirement_set_id) REFERENCES catalog.verification_targets(run_id,source_version_id,requirement_set_id) ON DELETE RESTRICT,FOREIGN KEY(run_id,environment_id,profile_id) REFERENCES catalog.verification_runs(id,environment_id,profile_id) ON DELETE RESTRICT,UNIQUE(id,run_id,source_version_id,requirement_set_id,environment_id,profile_id),UNIQUE(id,source_version_id,requirement_set_id,environment_id,profile_id));
CREATE TABLE catalog.bundle_cases(bundle_id uuid NOT NULL,run_id uuid NOT NULL,source_version_id uuid NOT NULL,requirement_set_id uuid NOT NULL,environment_id uuid NOT NULL,profile_id uuid NOT NULL,seed integer NOT NULL,viewport text NOT NULL,case_attempt_id uuid NOT NULL,PRIMARY KEY(bundle_id,seed,viewport),FOREIGN KEY(bundle_id,run_id,source_version_id,requirement_set_id,environment_id,profile_id) REFERENCES catalog.evidence_bundles(id,run_id,source_version_id,requirement_set_id,environment_id,profile_id) ON DELETE RESTRICT,FOREIGN KEY(case_attempt_id,run_id,source_version_id,requirement_set_id,environment_id,profile_id,seed,viewport) REFERENCES catalog.case_attempts(id,run_id,source_version_id,requirement_set_id,environment_id,profile_id,seed,viewport) ON DELETE RESTRICT);
ALTER TABLE catalog.assessments ADD COLUMN bundle_id uuid NOT NULL;
ALTER TABLE catalog.assessments ADD FOREIGN KEY(bundle_id,source_version_id,requirement_set_id,environment_id,profile_id) REFERENCES catalog.evidence_bundles(id,source_version_id,requirement_set_id,environment_id,profile_id) ON DELETE RESTRICT;
CREATE TABLE catalog.activation_events(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),release_id uuid NOT NULL REFERENCES catalog.activation_releases ON DELETE RESTRICT,scope text NOT NULL,generation bigint NOT NULL,actor_ref text NOT NULL,kind text NOT NULL CHECK(kind IN('published','withdrawn')),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope,generation));
CREATE TABLE catalog.policy_revocations(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),source_version_id uuid NOT NULL REFERENCES catalog.source_versions ON DELETE RESTRICT,scope text NOT NULL,reason_code text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE practice_private.principals ADD COLUMN ownership_generation bigint NOT NULL DEFAULT 0 CHECK(ownership_generation>=0);
CREATE TABLE practice_private.credentials(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),principal_id uuid NOT NULL,principal_kind text NOT NULL DEFAULT 'anonymous' CHECK(principal_kind='anonymous'),credential_hash catalog.digest256 NOT NULL UNIQUE,revoked_at timestamptz,FOREIGN KEY(principal_id,principal_kind) REFERENCES practice_private.principals(id,kind) ON DELETE RESTRICT);
CREATE TABLE practice_private.events(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),principal_id uuid NOT NULL REFERENCES practice_private.principals ON DELETE RESTRICT,actor_account_id uuid REFERENCES auth.users(id) ON DELETE RESTRICT,kind text NOT NULL,reason_code text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE practice_private.account_claims ADD COLUMN consent_event_id uuid REFERENCES practice_private.events ON DELETE RESTRICT,ADD COLUMN proof_event_id uuid REFERENCES practice_private.events ON DELETE RESTRICT;
CREATE TABLE practice_private.draft_revisions(draft_id uuid NOT NULL REFERENCES practice_private.drafts ON DELETE RESTRICT,revision bigint NOT NULL CHECK(revision>=0),answers jsonb NOT NULL CHECK(practice_private.valid_pairs(answers)),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(draft_id,revision));
CREATE TABLE practice_private.continuations(owner_id uuid PRIMARY KEY REFERENCES practice_private.principals ON DELETE RESTRICT,session_id uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(session_id,owner_id) REFERENCES practice_private.sessions(id,owner_id) ON DELETE RESTRICT);
ALTER TABLE practice_private.drafts ADD CHECK(octet_length(answers::text)<=500000);
ALTER TABLE practice_private.attempts ADD CHECK(octet_length(answers::text)<=500000);
CREATE INDEX operations_owner_active ON practice_private.submission_operations(owner_id,session_id) WHERE state IN('queued','in-flight','uncertain');
CREATE INDEX case_attempt_history ON catalog.case_attempts(run_id,source_version_id,seed,viewport,ordinal DESC);
CREATE FUNCTION practice_private.valid_feedback(value jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog AS $$ SELECT CASE WHEN jsonb_typeof(value)<>'object' THEN false ELSE coalesce(jsonb_typeof(value->'message')='string' AND jsonb_typeof(value->'summary')='string' AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(value) k WHERE k NOT IN('message','summary')),false) END $$;
CREATE FUNCTION practice_private.valid_field_feedback(value jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$ DECLARE f jsonb;k text;BEGIN IF jsonb_typeof(value)<>'array' THEN RETURN false;END IF;FOR f IN SELECT * FROM jsonb_array_elements(value) LOOP IF jsonb_typeof(f)<>'object' OR jsonb_typeof(f->'name') IS DISTINCT FROM 'string' OR jsonb_typeof(f->'message') IS DISTINCT FROM 'string' OR coalesce(f->>'status','') NOT IN('correct','incorrect','partial','invalid','unanswered','ungraded') THEN RETURN false;END IF;FOR k IN SELECT jsonb_object_keys(f) LOOP IF k NOT IN('name','status','score','message','reason') THEN RETURN false;END IF;END LOOP;IF f ? 'score' AND jsonb_typeof(f->'score') NOT IN('number','null') THEN RETURN false;END IF;IF jsonb_typeof(f->'score')='number' AND (f->>'score')::numeric NOT BETWEEN 0 AND 1 THEN RETURN false;END IF;IF f ? 'reason' AND jsonb_typeof(f->'reason') NOT IN('string','null') THEN RETURN false;END IF;END LOOP;RETURN true;END $$;
ALTER TABLE practice_private.attempts ADD COLUMN feedback jsonb NOT NULL DEFAULT '{"message":"","summary":""}'::jsonb CHECK(practice_private.valid_feedback(feedback)),ADD COLUMN field_feedback jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(practice_private.valid_field_feedback(field_feedback));
REVOKE ALL ON ALL TABLES IN SCHEMA catalog,practice_private FROM PUBLIC,anon,authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA catalog,practice_private FROM PUBLIC,anon,authenticated;
COMMIT;
